import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.Stack;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int n = Integer.parseInt(br.readLine().trim());long[] a = new long[n];for (int i = 0; i < n; i++) {a[i] = Long.parseLong(br.readLine().trim());}int[] nextGreater = new int[n];int[] nextSmaller = new int[n];for (int i = 0; i < n; i++) {nextGreater[i] = -1;nextSmaller[i] = -1;}Stack<Integer> stack = new Stack<Integer>();for (int i = 0; i < n; i++) {while (!stack.isEmpty() && a[stack.peek()] < a[i]) {nextGreater[stack.pop()] = i;}stack.push(i);}stack.clear();for (int i = 0; i < n; i++) {while (!stack.isEmpty() && a[stack.peek()] > a[i]) {nextSmaller[stack.pop()] = i;}stack.push(i);}StringBuilder sb = new StringBuilder();for (int i = 0; i < n; i++) {int f = nextGreater[i];if (f == -1) {sb.append("-1 ");} else {int g = nextSmaller[f];if (g == -1) {sb.append("-1 ");} else {sb.append(a[g]).append(" ");}}}System.out.println(sb.toString().trim());}}